COMMENT ON COLUMN substrates.reflection_results IS 'This substrate''s per-condition reflection results.';

-- ----------------------------------------------------------------------------
-- AnswerKeyResults: Per (substrate, input history) answer-key outcomes, ingested from a fresh run of conformance/run.py (conformance/matrix.json). Witnessed data, never recomputed here.
-- ----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS answer_key_results (
  answer_key_result_id                TEXT                 PRIMARY KEY          -- Stored identity: '<SubstrateId>__<InputHistoryId>'.
);
ALTER TABLE answer_key_results ADD COLUMN IF NOT EXISTS substrate TEXT;                             -- The substrate this result was computed for.
