ALTER TABLE answer_key_results ADD COLUMN IF NOT EXISTS traces_produced INTEGER;                    -- Number of distinct traces this substrate produced for this input history (witnessed by conformance/run.py).
ALTER TABLE answer_key_results ADD COLUMN IF NOT EXISTS permitted INTEGER;                          -- Size of the permitted (expected) trace set for this input history (witnessed by tools/gen_expected.py).
ALTER TABLE answer_key_results ADD COLUMN IF NOT EXISTS outcome TEXT;                               -- 'pass' if every produced trace was inside the permitted set, else 'fail'. Witnessed by conformance/run.py; never recomputed here.
COMMENT ON TABLE answer_key_results IS 'Per (substrate, input history) answer-key outcomes, ingested from a fresh run of conformance/run.py (conformance/matrix.json). Witnessed data, never recomputed here.';
COMMENT ON COLUMN answer_key_results.answer_key_result_id IS 'Stored identity: ''<SubstrateId>__<InputHistoryId>''.';
COMMENT ON COLUMN answer_key_results.substrate IS 'The substrate this result was computed for.';
COMMENT ON COLUMN answer_key_results.input_history IS 'The input history this result was computed against.';
COMMENT ON COLUMN answer_key_results.traces_produced IS 'Number of distinct traces this substrate produced for this input history (witnessed by conformance/run.py).';
COMMENT ON COLUMN answer_key_results.permitted IS 'Size of the permitted (expected) trace set for this input history (witnessed by tools/gen_expected.py).';
COMMENT ON COLUMN answer_key_results.outcome IS '''pass'' if every produced trace was inside the permitted set, else ''fail''. Witnessed by conformance/run.py; never recomputed here.';

-- ----------------------------------------------------------------------------
