CREATE OR REPLACE FUNCTION get_reflection_conditions_description(p_condition_id TEXT)
RETURNS TEXT AS $$
  SELECT (SELECT description FROM reflection_conditions WHERE condition_id = p_condition_id);
$$ LANGUAGE sql STABLE;

-- calc_reflection_results_name
-- Field: ReflectionResults.Name
-- Type: calculated | DataType: string | Returns: TEXT


CREATE OR REPLACE FUNCTION calc_reflection_results_name(p_reflection_result_id TEXT)
RETURNS TEXT AS $$
  SELECT ((SELECT NULLIF(reflection_result_id, '') FROM reflection_results WHERE reflection_result_id = p_reflection_result_id))::text;
$$ LANGUAGE sql STABLE;

