-- ----------------------------------------------------------------------------
-- vw_edb_relations: The R0 spec's extensional database relations (r0/spec.json's 'edb' map): the fixed vocabulary every rule and command is built from.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_edb_relations CASCADE;
CREATE VIEW vw_edb_relations WITH (security_invoker = ON) AS
SELECT
  t.relation_id,                                                                -- Stored identity: the EDB relation name from r0/spec.json's edb map (e.g. 'Warehouse').
  t.fields,                                                                     -- JSON array of the relation's field names, verbatim from spec.json (e.g. '["id"]').
  t.field_count,                                                                -- Number of fields, counted once at transcription time.
  t.description,                                                                -- What this EDB relation models in the warehouse-network domain.
  calc_edb_relations_name(t.relation_id) AS name,                               -- Display alias.
  t.seed_facts,                                                                 -- h0 seed facts whose Relation is this EDB relation.
  t.transition_effects                                                          -- Transition effects that assert/retract into this relation.
FROM edb_relations t;

-- ----------------------------------------------------------------------------
-- vw_commands: The R0 spec's commands (r0/spec.json's 'commands' map): the only way an input history can act on the state.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_commands CASCADE;
CREATE VIEW vw_commands WITH (security_invoker = ON) AS
SELECT
  t.command_id,                                                                 -- Stored identity: the command name from r0/spec.json's commands map (e.g. 'AddRoute').
  t.params,                                                                     -- JSON array of the command's parameter names, verbatim from spec.json.
  t.param_count,                                                                -- Number of parameters, counted once at transcription time.
  t.description,                                                                -- What issuing this command means in the warehouse-network domain.
  calc_commands_name(t.command_id) AS name,                                     -- Display alias.
  t.transitions                                                                 -- Transitions this command can fire.
FROM commands t;

-- ----------------------------------------------------------------------------
-- vw_rules: Every stratified Datalog-with-negation-and-aggregation rule in the R0 spec (r0/spec.json's 'rules' array), including guard/effect/event rules for transitions and the two integrity-constraint rules.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_rules CASCADE;
CREATE VIEW vw_rules WITH (security_invoker = ON) AS
SELECT
  t.rule_id,                                                                    -- Stored identity: the rule's 'id' in r0/spec.json's rules array (e.g. 'reach_base').
  t.head_predicate,                                                             -- The rule's head predicate name (head[0] in spec.json), e.g. 'Reachable'.
  t.kind,                                                                       -- 'rule' for a body-clause rule, 'aggregation' for an agg-clause rule (spec.json's 'agg' key).
  t.head_json,                                                                  -- The rule's head tuple, verbatim JSON from spec.json.
  t.body_json,                                                                  -- The rule's body clause list, verbatim JSON from spec.json (null for aggregation rules).
  t.agg_json,                                                                   -- The rule's agg clause, verbatim JSON from spec.json (null for body rules).
  t.paper_section_ref,                                                          -- CMCC-Core Representation Theorem section(s) this rule exercises.
  t.description,                                                                -- What the rule computes and, for reflection.py, which G_R node it constructs.
  calc_rules_name(t.rule_id) AS name,                                           -- Display alias.
  t.guarded_transitions,                                                        -- Transitions whose Guard is this rule.
  t.transition_effects,                                                         -- Transition effects whose FromRule is this rule.
  t.transition_events,                                                          -- Transition events whose FromRule is this rule.
  t.integrity_constraints                                                       -- Integrity constraints whose Rule is this rule.
FROM rules t;

-- ----------------------------------------------------------------------------
-- vw_transitions: The R0 spec's transitions (r0/spec.json's 'transitions' array): command + guard pairs that may fire, each with its effects and events.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_transitions CASCADE;
CREATE VIEW vw_transitions WITH (security_invoker = ON) AS
SELECT
  t.transition_id,                                                              -- Stored identity: the transition's 'name' in r0/spec.json's transitions array (e.g. 'AddRoute').
  t.command,                                                                    -- The command that can fire this transition.
  t.guard,                                                                      -- The rule whose head predicate gates this transition.
  t.description,                                                                -- What this transition does when its guard is satisfied.
  calc_transitions_name(t.transition_id) AS name,                               -- Display alias.
  t.effects,                                                                    -- This transition's ordered assert/retract effects.
  t.events                                                                      -- This transition's emitted events.
FROM transitions t;

-- ----------------------------------------------------------------------------
-- vw_transition_effects: One row per (transition, effect) pair: an ordered assert/retract of a rule's derived tuples into an EDB relation.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_transition_effects CASCADE;
CREATE VIEW vw_transition_effects WITH (security_invoker = ON) AS
SELECT
  t.effect_id,                                                                  -- Stored identity: '<TransitionId>#effect<index>', ordered as in spec.json.
  t.transition,                                                                 -- The transition this effect belongs to.
  t.op,                                                                         -- 'assert' or 'retract'.
  t.relation,                                                                   -- The EDB relation this effect asserts into or retracts from.
  t.from_rule,                                                                  -- The rule whose derived tuples this effect applies.
  calc_transition_effects_name(t.effect_id) AS name                             -- Display alias.
FROM transition_effects t;

-- ----------------------------------------------------------------------------
-- vw_transition_events: One row per (transition, event) pair: an event relation emitted when the transition fires.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_transition_events CASCADE;
CREATE VIEW vw_transition_events WITH (security_invoker = ON) AS
SELECT
  t.event_id,                                                                   -- Stored identity: '<TransitionId>#event<index>', ordered as in spec.json.
  t.transition,                                                                 -- The transition this event belongs to.
  t.event_relation,                                                             -- The event relation name emitted (e.g. 'RouteAdded'); not an EDB relation.
  t.from_rule,                                                                  -- The rule whose derived tuples produce this event.
  calc_transition_events_name(t.event_id) AS name                               -- Display alias.
FROM transition_events t;

-- ----------------------------------------------------------------------------
-- vw_integrity_constraints: The R0 spec's integrity constraints (r0/spec.json's 'constraints' array): predicates whose nonempty derivation rejects a transition. Named IntegrityConstraints, not Constraints -- rulebook-to-rulespeak v2026.09.17.2011 treats a table literally named 'Constraints' as a reserved word and fails the whole build with "Entity '' does not resolve to any table."
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_integrity_constraints CASCADE;
CREATE VIEW vw_integrity_constraints WITH (security_invoker = ON) AS
SELECT
  t.constraint_id,                                                              -- Stored identity: the constraint's head predicate name, verbatim from spec.json's constraints array (e.g. 'NegativeCap').
  t.rule,                                                                       -- The rule that derives this constraint's violations.
  t.description,                                                                -- What a nonempty derivation of this predicate means, and which transition it rejects.
  calc_integrity_constraints_name(t.constraint_id) AS name                      -- Display alias.
FROM integrity_constraints t;

-- ----------------------------------------------------------------------------
-- vw_observables: The R0 spec's observables (r0/spec.json's 'observables' map): the predicates exposed in Obs_R0(c, i, h), section 9.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_observables CASCADE;
CREATE VIEW vw_observables WITH (security_invoker = ON) AS
SELECT
  t.observable_id,                                                              -- Stored identity: the observable's key in spec.json's observables map (e.g. 'reachable').
  t.exposed_predicate,                                                          -- The predicate this observable exposes (e.g. 'Reachable').
  t.description,                                                                -- Why this predicate is exposed as an observable in Obs_R0(c, i, h).
  calc_observables_name(t.observable_id) AS name                                -- Display alias.
FROM observables t;

-- ----------------------------------------------------------------------------
-- vw_seed_facts: The R0 spec's initial history h0 (r0/spec.json's 'h0' array): the seed facts every input history starts from.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_seed_facts CASCADE;
CREATE VIEW vw_seed_facts WITH (security_invoker = ON) AS
SELECT
  t.seed_fact_id,                                                               -- Stored identity: 'h0-<n>', where n is the fact's position in spec.json's h0 array.
  t.n,                                                                          -- The fact's 'n' (insertion order) in spec.json's h0 array.
  t.op,                                                                         -- 'assert' (h0 is assert-only).
  t.relation,                                                                   -- The EDB relation this seed fact populates.
  t.tuple_json,                                                                 -- The seeded tuple, verbatim JSON from spec.json.
  t.k,                                                                          -- Knowledge time of the seed fact (0 for all of h0).
  calc_seed_facts_name(t.seed_fact_id) AS name                                  -- Display alias.
FROM seed_facts t;

-- ----------------------------------------------------------------------------
-- vw_input_histories: The two input histories this example runs (r0/inputs/*.json): what each is designed to exercise.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_input_histories CASCADE;
CREATE VIEW vw_input_histories WITH (security_invoker = ON) AS
SELECT
  t.input_history_id,                                                           -- Stored identity: the input file's stem under r0/inputs/ (e.g. 'i1-routes').
  t.source_file,                                                                -- Path to the input history file, relative to the project root.
  t.event_count,                                                                -- Number of command events in the input history, counted once at transcription time.
  t.description,                                                                -- What this input history is designed to exercise.
  calc_input_histories_name(t.input_history_id) AS name,                        -- Display alias.
  t.answer_key_results                                                          -- Per-substrate answer-key results computed against this input history.
FROM input_histories t;

-- ----------------------------------------------------------------------------
-- vw_reflection_conditions: The six conditions of constructor reflection, section 13 of the paper.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_reflection_conditions CASCADE;
CREATE VIEW vw_reflection_conditions WITH (security_invoker = ON) AS
SELECT
  t.condition_id,                                                               -- Stored identity, matching conformance/matrix.json's condition keys (e.g. '1_constructor_preservation').
  t.condition_number,                                                           -- The condition's number in §13 (1-6).
  t.title,                                                                      -- Short name of the condition.
  t.paper_section_ref,                                                          -- Paper section this condition is defined in.
  t.description,                                                                -- What the condition checks on the substrate artifact's call graph.
  calc_reflection_conditions_name(t.condition_id) AS name,                      -- Display alias.
  t.reflection_results                                                          -- Per-substrate pass/fail/delegated outcomes for this condition.
FROM reflection_conditions t;

-- ----------------------------------------------------------------------------
-- vw_substrates: The three substrates checked against the R0 spec: transparent (the real representation) and two controls, tangled and interpreter, that are expected to fail reflection on purpose.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_substrates CASCADE;
CREATE VIEW vw_substrates WITH (security_invoker = ON) AS
SELECT
  t.substrate_id,                                                               -- Stored identity, matching conformance/matrix.json's substrate keys.
  t.description,                                                                -- What this substrate is and how it is generated.
  t.paper_section_ref,                                                          -- Paper section(s) this substrate demonstrates.
  t.is_control,                                                                 -- True for the two substrates that are deliberately expected to fail reflection (tangled, interpreter).
  calc_substrates_name(t.substrate_id) AS name,                                 -- Display alias.
  t.answer_key_results,                                                         -- This substrate's per-input-history answer-key results.
  t.reflection_results,                                                         -- This substrate's per-condition reflection results.
  calc_substrates_answer_key_result_count(t.substrate_id) AS answer_key_result_count,-- Number of answer-key results recorded for this substrate.
  calc_substrates_answer_key_fail_count(t.substrate_id) AS answer_key_fail_count,-- Number of answer-key results recorded as a failure for this substrate.
  calc_substrates_answer_key_ok(t.substrate_id) AS answer_key_ok,               -- True when every recorded answer-key result for this substrate passed (§11).
  calc_substrates_reflection_result_count(t.substrate_id) AS reflection_result_count,-- Number of reflection results recorded for this substrate.
  calc_substrates_reflection_fail_count(t.substrate_id) AS reflection_fail_count,-- Number of reflection conditions recorded as a failure for this substrate.
  calc_substrates_reflection_ok(t.substrate_id) AS reflection_ok,               -- True when no recorded reflection condition failed for this substrate (§13). Delegated conditions never count as a failure.
  calc_substrates_conformant(t.substrate_id) AS conformant                      -- True only when this substrate passes both gates: the answer key and reflection.
FROM substrates t;

-- ----------------------------------------------------------------------------
-- vw_answer_key_results: Per (substrate, input history) answer-key outcomes, ingested from a fresh run of conformance/run.py (conformance/matrix.json). Witnessed data, never recomputed here.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_answer_key_results CASCADE;
CREATE VIEW vw_answer_key_results WITH (security_invoker = ON) AS
SELECT
  t.answer_key_result_id,                                                       -- Stored identity: '<SubstrateId>__<InputHistoryId>'.
  t.substrate,                                                                  -- The substrate this result was computed for.
  t.input_history,                                                              -- The input history this result was computed against.
  t.traces_produced,                                                            -- Number of distinct traces this substrate produced for this input history (witnessed by conformance/run.py).
  t.permitted,                                                                  -- Size of the permitted (expected) trace set for this input history (witnessed by tools/gen_expected.py).
  t.outcome,                                                                    -- 'pass' if every produced trace was inside the permitted set, else 'fail'. Witnessed by conformance/run.py; never recomputed here.
  calc_answer_key_results_name(t.answer_key_result_id) AS name                  -- Display alias.
FROM answer_key_results t;

-- ----------------------------------------------------------------------------
-- vw_reflection_results: Per (substrate, reflection condition) outcomes, ingested from a fresh run of conformance/run.py (conformance/matrix.json). Witnessed data, never recomputed here.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_reflection_results CASCADE;
CREATE VIEW vw_reflection_results WITH (security_invoker = ON) AS
SELECT
  t.reflection_result_id,                                                       -- Stored identity: '<SubstrateId>__<ConditionId>'.
  t.substrate,                                                                  -- The substrate this reflection outcome was computed for.
  t.reflection_condition,                                                       -- The §13 condition this outcome is for.
  t.outcome,                                                                    -- 'pass', 'fail' or 'delegated' (condition 4 is always delegated to the answer key by design). Witnessed by tools/reflection_check.py; never recomputed here.
  calc_reflection_results_name(t.reflection_result_id) AS name                  -- Display alias.
FROM reflection_results t;



